INSERT INTO `courses_engineeringcourse` VALUES ('19a034705c794859836fe62b61c22f17','Python Programming: Beginner to Advanced Complete Guide','Master Python from scratch to advanced concepts with projects, quizzes, and real-world applications.','This course takes you from Python basics to advanced programming concepts with clear explanations, practical exercises, and real projects. It combines structured video lessons, quizzes, and hands-on coding to help you gain strong programming skills and confidence.','course_thumbnails/Gemini_Generated_Image_6v39lj6v39lj6v39.png','40 Hours','2025-09-21','2025-09-21 06:34:26.674000',1,NULL,'Youtube','beginner',1,1,'[\"Build a solid foundation in Python: syntax, data types, control flow, functions, OOP, and advanced features like decorators and generators\", \"Apply your knowledge through projects such as calculators, pattern printing, file handling, and data structure applications\"]','[\"No Prior Programming Experience Needed – This course starts from absolute basics.  A Computer or Laptop – Windows, macOS, or Linux with at least 4 GB RAM.  Internet Connection – To watch videos, access resources, and download Python.  Python 3.x Installed – (Installation guide included in the course).  A Code Editor/IDE – Such as PyCharm, VS Code, or IDLE (setup instructions provided).\"]','programming',NULL);
/*!40000 ALTER TABLE `courses_engineeringcourse` ENABLE KEYS */;
